import { writeFileSync } from 'node:fs';

const TAB = String.fromCharCode(9);
const CR = String.fromCharCode(13);
const LF = String.fromCharCode(10);
const SQ = String.fromCharCode(39);
const DQ = String.fromCharCode(34);
const BS = String.fromCharCode(92);

const cases = [
  ['--help=it' + SQ + 's'],
  ['--help=a' + LF + 'b'],
  ['--help=' + '日本'],
  ['--help=a' + BS + 'b'],
  ['-h=' + TAB],
  ['--help=' + SQ + DQ],
  ['--help=' + DQ],
  ['--help=' + '😀'],
  ['--help=' + CR],
  ['--help= x '],
  ['-h', '--help=x'],
  ['--help=' + 'é'],
  ['--help=' + String.fromCharCode(0x7f)],
  ['--help=' + String.fromCharCode(0x1b)],
  ['--help=' + String.fromCharCode(0x85)],
  ['--help=' + String.fromCharCode(0xa0)],
  ['--help=' + ' '],
  ['--h=' + SQ],
];
writeFileSync('/workspace/corpus/tmp-repr.json', JSON.stringify(cases));

import { writeFileSync } from 'node:fs';

const LF = String.fromCharCode(10);
const CR = String.fromCharCode(13);

// One representative code point from every Unicode Nd range, plus near-misses.
const ndReps = [
  0x0030, 0x0660, 0x06f0, 0x07c0, 0x0966, 0x09e6, 0x0a66, 0x0ae6, 0x0b66,
  0x0be6, 0x0c66, 0x0ce6, 0x0d66, 0x0de6, 0x0e50, 0x0ed0, 0x0f20, 0x1040,
  0x1090, 0x17e0, 0x1810, 0x1946, 0x19d0, 0x1a80, 0x1a90, 0x1b50, 0x1bb0,
  0x1c40, 0x1c50, 0xa620, 0xa8d0, 0xa900, 0xa9d0, 0xa9f0, 0xaa50, 0xabf0,
  0xff10, 0x104a0, 0x10d30, 0x11066, 0x110f0, 0x11136, 0x111d0, 0x112f0,
  0x11450, 0x114d0, 0x11650, 0x116c0, 0x11730, 0x118e0, 0x11950, 0x11c50,
  0x11d50, 0x11da0, 0x16a60, 0x16ac0, 0x16b50, 0x1d7ce, 0x1e140, 0x1e2f0,
  0x1e950, 0x1fbf0,
];
const nonNd = [
  0x00b2, 0x00b9, 0x00bd, 0x2070, 0x2160, 0x2460, 0x3007, 0x3021, 0x0f2a,
  0x0bf0, 0x4e00, 0x3220, 0x00b0, 0x2044,
];

const cases = [];
for (const cp of ndReps) cases.push(['--a', '-' + String.fromCodePoint(cp)]);
for (const cp of nonNd) cases.push(['--a', '-' + String.fromCodePoint(cp)]);
// anchoring quirks: Python's `$` also matches just before a single trailing \n
cases.push(['--a', '-1' + LF]);
cases.push(['--a', '-1' + LF + LF]);
cases.push(['--a', '-1' + LF + 'x']);
cases.push(['--a', '-1.5' + LF]);
cases.push(['--a', '-.5' + LF]);
cases.push(['--a', '-1' + CR]);
cases.push(['--a', '-1' + CR + LF]);
cases.push(['--a', LF + '-1']);
writeFileSync('/workspace/corpus/tmp-nd.json', JSON.stringify(cases));
console.log('cases: ' + cases.length);

