node /workspace/probe/gen-cli-nd.mjs && node /workspace/harness/probe.mjs /workspace/corpus/tmp-nd.json > /workspace/tmp/nd-out.txt 2>&1; node -e '
const fs=require("fs");
const txt=fs.readFileSync("/workspace/tmp/nd-out.txt","utf8");
const blocks=txt.split("\n\n");
let ok=[],bad=[];
for(const b of blocks){
  if(!b.trim())continue;
  const lines=b.split("\n");
  const inl=lines[0].slice(7);
  const code=(b.split("CODE : ")[1]||"").trim();
  const argv=JSON.parse(inl);
  const v=argv[1];
  const cps=Array.from(v).map(c=>c.codePointAt(0).toString(16)).join(" ");
  (code==="0"?ok:bad).push(cps);
}
console.log("ACCEPTED (treated as value): "+ok.length);
console.log(ok.join(" | "));
console.log("REJECTED (option-like): "+bad.length);
console.log(bad.join(" | "));
'
